sources.check.lua:
return rule('sv.check', {'actor', 'attribute:text', 'mode:text'}, function(r, actor, attribute, mode)
  r.call('sv.automation', actor)
  return r.call('sv.check.core', actor, attribute, mode)
end, {dependencies={'sv.automation', 'sv.check.core'}})

sources.inventory.lua:
return rule('sv.inventory', {'actor', 'operation:text', 'slot:amount', 'value:amount'}, function(r, actor, operation, slot, value)
  r.call('sv.automation', actor)
  return r.call('sv.inventory.core', actor, operation, slot, value)
end, {dependencies={'sv.automation', 'sv.inventory.core'}})

sources.ready.lua:
return rule('sv.ready', {'actor', 'ready:choice'}, function(r, actor, ready)
  assert(r.matches(actor, 'sv.character') and r.number(actor, 'approved') == 1, 'SV_NOT_APPROVED')
  r.set(actor, 'ready', ready and 1 or 0)
  return {ready=ready}
end)

sources.travel.lua:
return rule('sv.travel', {'actor', 'location:amount'}, function(r, actor, location)
  assert(r.matches(actor, 'sv.character') and r.number(actor, 'approved') == 1, 'SV_NOT_APPROVED')
  local exists = false
  for _, place in ipairs(r.readData('game.json').locations) do
    if place.index == location then exists = true end
  end
  assert(exists, 'SV_LOCATION')
  r.set(actor, 'location', location)
  return {location=location}
end, {kp=true})

sources.remove.lua:
return rule('sv.remove', {'actor', 'slot:amount'}, function(r, actor, slot)
  assert(r.matches(actor, 'sv.character') and slot >= 1 and slot <= 20, 'SV_SLOT')
  local item = r.number(actor, 'item' .. slot)
  assert(item > 0, 'SV_EMPTY_SLOT')
  for _, prefix in ipairs({'item', 'uses', 'ticks'}) do r.set(actor, prefix .. slot, 0) end
  if r.number(actor, 'litSlot') == slot then r.set(actor, 'litSlot', 0) end
  return {removed=item, slot=slot}
end, {kp=true})

sources.morale.lua:
return rule('sv.morale', {'actor'}, function(r, actor)
  assert((r.matches(actor, 'sv.npc') or r.number(actor, 'isNpc') == 1), 'SV_NOT_NPC')
  local rolled = r.roll(20)
  local target = r.number(actor, 'wil')
  r.set(actor, 'lastRoll', rolled)
  return {attribute='wil', rolled=rolled, target=target, passed=rolled<=target}
end, {kp=true})

sources.adjudicate.lua:
return rule('sv.adjudicate', {'actor', 'kind:text', 'attribute:text', 'mode:text', 'operation:text', 'slot:amount', 'value:amount'}, function(r, actor, kind, attribute, mode, operation, slot, value)
  if kind == 'check' then return r.call('sv.check.core', actor, attribute, mode) end
  if kind == 'inventory' then return r.call('sv.inventory.core', actor, operation, slot, value) end
  error('SV_RULING_KIND')
end, {kp=true, dependencies={'sv.check.core', 'sv.inventory.core'}})

